param([string]$SourceRoot=$PSScriptRoot)
$ErrorActionPreference='Stop'
$target=Join-Path $env:LOCALAPPDATA 'BIMLog\LensNext\Revit2026';$manifestRoot=Join-Path $env:APPDATA 'Autodesk\Revit\Addins\2026';$manifest=Join-Path $manifestRoot 'BIMLogLensNext.Revit2026.addin'
if(-not(Test-Path -LiteralPath (Join-Path $SourceRoot 'BIMLogLensNext'))){throw 'The verified BIMLogLensNext package folder is missing.'}
$backup="$target.rollback";if(Test-Path -LiteralPath $backup){Remove-Item -LiteralPath $backup -Recurse -Force};if(Test-Path -LiteralPath $target){Move-Item -LiteralPath $target -Destination $backup}
try{New-Item -ItemType Directory -Path $target -Force|Out-Null;Copy-Item -LiteralPath (Join-Path $SourceRoot 'BIMLogLensNext\*') -Destination $target -Recurse -Force;New-Item -ItemType Directory -Path $manifestRoot -Force|Out-Null;$xml=Get-Content -LiteralPath (Join-Path $SourceRoot 'BIMLogLensNext.Revit2026.addin') -Raw;$xml=$xml.Replace('<Assembly>BIMLogLensNext.Revit2026.dll</Assembly>',"<Assembly>$target\BIMLogLensNext.Revit2026.dll</Assembly>");Set-Content -LiteralPath $manifest -Value $xml -Encoding UTF8}catch{if(Test-Path -LiteralPath $target){Remove-Item -LiteralPath $target -Recurse -Force};if(Test-Path -LiteralPath $backup){Move-Item -LiteralPath $backup -Destination $target};throw}
Write-Output "Installed BIMLog Lens for Revit 2026.5+ (.NET 10). Restart Revit to load the registered add-in."
